list.definition:
from(bucket: "roct_stat")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> keep(columns: ["svc_env", "svc_name"])
  |> map(fn: (r) => ({
      r with
      _value: r.svc_name + r.svc_env
  }))
  |> group(columns: [])
  |> distinct(column: "_value")
  |> sort(columns: ["_value"])

